script:
frappe.ui.form.on("Doctor", {
    refresh(frm) {

        frm.add_custom_button("Create Appointment", function () {

            frappe.new_doc("Hospital Appointment", {
                doctor: frm.doc.name
            });

        });

    }
});

frappe.ui.form.on("Patient", {
    refresh(frm) {

        frm.add_custom_button("Say Hello", function() {

            frappe.call({
                method: "hospital_management.api.hello",
                args: {
                    name: frm.doc.patient_name
                },
                callback: function(r) {
                    frappe.msgprint(r.message);
                }
            });

        });

    }
});

frappe.ui.form.on("Task", {
    refresh(frm) {
        frm.add_custom_button("Create Task Using Dialog", () => {

            let d = new frappe.ui.Dialog({
                title: "Create New Task",
                fields: [
                    {
                        label: "Task Subject",
                        fieldname: "task_subject",
                        fieldtype: "Data",
                        reqd: 1
                    }
                ],
                primary_action_label: "Create",
                primary_action(values) {

                    frappe.call({
                        method: "hospital_management.api.create_task",
                        args: {
                            task_subject: values.task_subject
                        },
                        callback: function(r) {

                            frappe.msgprint(
                                "Task Created Successfully: " + r.message
                            );

                            d.hide();
                        }
                    });

                }
            });

            d.show();

        });
    }
});

frappe.ui.form.on('User', {
    refresh(frm) {
        frm.add_custom_button('Send Welcome Email', function() {
            frappe.msgprint('Email Sent!');
        }, 'Actions');
    }
});
